c.python:
class Solution:
    def removeTrailingZeros(self, num: str) -> str:
        i = len(num) - 1
        while num[i] == '0':
            i -= 1
        return num[:i + 1]

c.cpp:
class Solution {
public:
    string removeTrailingZeros(string num) {
        int i = num.size() - 1;
        while (num[i] == '0') --i;
        return num.substr(0, i + 1);
    }
};

